    const Section(
      title: 'DOMAIN B: PROBLEM SOLVING',
      content: 'The attending asks you to explain the pathophysiology of neurogenic claudication, the role of EMG in lumbar stenosis, and how you distinguish this from other causes of leg pain with walking.',
